wBox="0 0 54 54"><path fill="currentColor" d="M22.031 19.687a1 1 0 0 1 1.515-.858l12.188 7.313a1 1 0 0 1 0 1.715L23.546 35.17a1 1 0 0 1-1.515-.857V19.687Z"></path></svg><!--]--></div></div></button><!--teleport start--><!--teleport end--></div></div><div class="about-apply-box__body"><p class="u-text-headings-small">Book your visit and take the first step towards your healthiest, most confident smile!</p><a class="button button--type-secondary button--icon-end about-apply-box__cta-button" href="tel:7796376170" target="_blank"><div class="button__text u-text-body-button"><!--[-->Book an Appointment<!--]--></div><!----></a></div></div></div><!--]--></div></div><!--]--></div></div></div><div class="reveal-block__timeline"><div class="reveal-block__timeline-item reveal-block__timeline-item--intro"></div><div class="reveal-block__timeline-item reveal-block__timeline-item--main"></div></div></div><!--]--></div></section>
